async (page) => {
  await page.evaluate(() => {
    window.__log = [];
    window.addEventListener('error', e => window.__log.push({t:'exception', m: String(e.message)}));
    window.addEventListener('unhandledrejection', e => window.__log.push({t:'rejection', m: String(e.reason && e.reason.message || e.reason)}));
  });
  const out = {};
  const buttons = await page.locator('button').all();
  const labels = [];
  for (const b of buttons) labels.push(await b.innerText());
  for (let i = 0; i < buttons.length; i++) {
    await page.evaluate(() => window.__log = []);
    await buttons[i].click();
    await page.waitForTimeout(2500);
    out[i + ':' + labels[i]] = await page.evaluate(() => window.__log);
  }
  return {out, html: (await page.content()).slice(0, 3000)};
}

